from taf.rfrl.l3_call.enviornment.classical_env.classical_env import ClassicalEnv


class ClassicalEnvSA(ClassicalEnv):
    def __init__(self):
        super(ClassicalEnvSA, self).__init__()
        self._ran = "classical"
        self._mode = "SA"
        self._node = "gnb"
        self._delta_id = "l3_call_gnb_delta_id"
        self._connection_alias = "l3_call_{}".format(self._node)

    def __str__(self):
        return "ClassicalEnvSA env instance for ran={}, mode={}, node={}".format(self._ran, self._mode,
                                                                                 self._node)

    def _make_cell_ids_dict(self):
        return {"gnb_cell": self._cell.id}
